package com.magicstudios.magiccore.modules.tools;
import java.time.Instant;import java.util.*;import java.util.concurrent.ConcurrentHashMap;import java.util.function.Function;import java.util.stream.Collectors;
public final class InMemoryCustomToolService implements CustomToolService{private final Map<String,ToolDefinition>definitions;private final Map<String,Instant>cooldowns=new ConcurrentHashMap<>();public InMemoryCustomToolService(List<ToolDefinition>definitions){this.definitions=definitions.stream().collect(Collectors.toUnmodifiableMap(ToolDefinition::id,Function.identity()));}@Override public List<ToolDefinition>definitions(){return definitions.values().stream().sorted(Comparator.comparing(ToolDefinition::id)).toList();}@Override public ToolDefinition require(String id){ToolDefinition value=definitions.get(id);if(value==null)throw new IllegalArgumentException("Unknown tool");return value;}@Override public boolean claimCooldown(UUID player,String toolId,Instant now){ToolDefinition tool=require(toolId);String key=player+":"+toolId;final boolean[]claimed={false};cooldowns.compute(key,(ignored,until)->{if(until==null||!until.isAfter(now)){claimed[0]=true;return now.plus(tool.cooldown());}return until;});return claimed[0];}}
